Here's how to implement this using ASP.NET Core's built-in Problem Details support plus a custom exception-handling middleware:

**1. Register Problem Details services in `Program.cs`:**

```csharp
builder.Services.AddProblemDetails();
```

**2. Create the exception-handling middleware:**

```csharp
// Middleware/ExceptionToProblemDetailsMiddleware.cs
using Microsoft.AspNetCore.Mvc;

public class ExceptionToProblemDetailsMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IProblemDetailsService _problemDetailsService;

    public ExceptionToProblemDetailsMiddleware(
        RequestDelegate next,
        IProblemDetailsService problemDetailsService)
    {
        _next = next;
        _problemDetailsService = problemDetailsService;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await _next(context);
        }
        catch (Exception ex)
        {
            var (statusCode, title) = ex switch
            {
                KeyNotFoundException   => (StatusCodes.Status404NotFound,    "Not Found"),
                ArgumentException      => (StatusCodes.Status400BadRequest,  "Bad Request"),
                InvalidOperationException => (StatusCodes.Status409Conflict, "Conflict"),
                _ => (StatusCodes.Status500InternalServerError, "An unexpected error occurred")
            };

            context.Response.StatusCode = statusCode;

            var problemDetails = new ProblemDetails
            {
                Status = statusCode,
                Title = title,
                Detail = statusCode == 500 ? null : ex.Message,
                Instance = context.Request.Path
            };

            await _problemDetailsService.WriteAsync(new ProblemDetailsContext
            {
                HttpContext = context,
                ProblemDetails = problemDetails
            });
        }
    }
}
```

**3. Wire it up in `Program.cs`:**

```csharp
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddProblemDetails();

var app = builder.Build();

app.UseMiddleware<ExceptionToProblemDetailsMiddleware>();

// Your endpoints — no try-catch needed
app.MapGet("/items/{id}", (int id) =>
{
    if (id < 0) throw new ArgumentException("ID must be positive");
    if (id == 0) throw new KeyNotFoundException("Item not found");
    if (id == 99) throw new InvalidOperationException("Item is locked");
    return Results.Ok(new { Id = id, Name = "Widget" });
});

app.Run();
```

**Key points:**

- `IProblemDetailsService` handles JSON serialization with the correct `application/problem+json` content type
- 500 errors suppress `ex.Message` to avoid leaking internals
- The middleware catches exceptions globally — no per-endpoint try-catch needed
- Add logging inside the `catch` (inject `ILogger<T>`) if you want to log the full exception for 500s
